// Home.js
import React, { useState } from 'react';
import TrackSearch from '../components/TrackSearch';

const Home = ({ isAuthorized, setIsAuthorized }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [submittedTerm, setSubmittedTerm] = useState('');

  const handleInputChange = (e) => {
    setSearchTerm(e.target.value);
  };

  const handleSearchSubmit = () => {
    console.log("Search submitted with term:", searchTerm);
    setSubmittedTerm(searchTerm);
  };

  const handleLogin = () => {
    console.log("Redirecting to Spotify for login");
    window.location.href = 'http://localhost:3001/api/login';
  };

  return (
    <div>
      <h1 className="title">Welcome to Track Similarity App</h1>
      <p className="description">Search for tracks by entering a track name, artist, or album below.</p>

      {!isAuthorized ? (
        <>
          <button className="login-button" onClick={handleLogin}>Login with Spotify</button>
          {console.log("User not authorized, displaying login button")}
        </>
      ) : (
        <>
          <div className="search-bar">
            <input
              type="text"
              placeholder="Enter track, artist, or album..."
              value={searchTerm}
              onChange={handleInputChange}
              className="text-input wide-text-input"
            />
            <button onClick={handleSearchSubmit} className="search-button">Search</button>
          </div>
          {console.log("User authorized, displaying search bar")}
        </>
      )}

      {/* Display TrackSearch results if a search term is submitted */}
      {isAuthorized && <TrackSearch searchTerm={submittedTerm} />}
    </div>
  );
};

export default Home;
